// Real brand glyphs rendered as inline SVG paths in their official brand
// colors — no external requests (CSP-safe). Marks whose official color is
// black/near-black are lifted to white so they stay visible on the dark
// surface. Path sources: Simple Icons (CC0), LobeHub icons (OpenAI, Groq,
// xAI, Together — MIT), Bootstrap Icons (Slack — MIT).
//
// `transform` normalizes optical size: every mark's bounding box is scaled to
// an 18-unit max dimension centered in the 24x24 box (precomputed from the
// source path bounds), so full-bleed and padded logos render equally sized.
interface BrandGlyph {
  /** SVG path data; multiple entries render as sibling <path> elements. */
  d: string[];
  /** Official brand color (dark marks lifted to white for the dark UI). */
  fill?: string;
  /** Brand gradient stops, bottom-left to top-right; takes over from fill. */
  gradient?: string[];
  /** Centers the mark and equalizes its optical size in the 24x24 box. */
  transform: string;
  /** LobeHub sources draw with the even-odd fill rule. */
  evenOdd?: boolean;
}

