// Fallback monograms for providers without a brand glyph (e.g. custom).
const MONOGRAM: Partial<Record<LLMProvider, string>> = {
  custom: '{}',
};

interface ProviderIconProps {
  provider: LLMProvider;
  className?: string;
}

/** Inline, brand-colored logo for a BYOK provider. Decorative. */
export function ProviderIcon({ provider, className }: ProviderIconProps) {
  const brand = BRAND[provider];

  if (brand) {
    const gradient = brand.gradient;
    // Duplicate ids across instances are fine: every definition is identical.
    const gradientId = `provider-gradient-${provider}`;
    return (
      <svg
        viewBox="0 0 24 24"
        className={className}
        role="img"
        aria-hidden
        fillRule={brand.evenOdd ? 'evenodd' : undefined}
      >
        {gradient && (
          <defs>
            <linearGradient id={gradientId} x1="0" y1="1" x2="1" y2="0">
              {gradient.map((color, i) => (
                <stop
                  key={color}
                  offset={`${(i / (gradient.length - 1)) * 100}%`}
                  stopColor={color}
                />
              ))}
            </linearGradient>
          </defs>
        )}
        <g
          transform={brand.transform}
          fill={gradient ? `url(#${gradientId})` : brand.fill}
        >
          {brand.d.map((d, i) => (
            <path key={i} d={d} />
          ))}
        </g>
      </svg>
    );
  }

  const mono = MONOGRAM[provider] ?? '?';
  return (
    <svg viewBox="0 0 24 24" className={className} role="img" aria-hidden fill="none">
      <rect
        x="1"
        y="1"
        width="22"
        height="22"
        rx="6"
        stroke="currentColor"
        strokeWidth="1.5"
        opacity="0.45"
      />
      <text
        x="12"
        y="12.5"
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={9}
        fontWeight={700}
        fill="currentColor"
        fontFamily="ui-monospace, SFMono-Regular, monospace"
      >
        {mono}
      </text>
    </svg>
  );
}

export default ProviderIcon;
